package com.splitmate.service;
import com.splitmate.api.ApiDtos.*; import com.splitmate.domain.*; import com.splitmate.repo.*; import org.springframework.data.domain.*; import org.springframework.http.HttpStatus; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.math.*; import java.time.*; import java.util.*; import java.util.stream.*;
@Service public class SplitMateService {
 final UserRepository users; final HouseholdRepository households; final MembershipRepository memberships; final ExpenseRepository expenses; final ExpenseShareRepository shares; final SettlementRepository settlements; final PasswordEncoder encoder;
 public SplitMateService(UserRepository u,HouseholdRepository h,MembershipRepository m,ExpenseRepository e,ExpenseShareRepository s,SettlementRepository st,PasswordEncoder p){users=u;households=h;memberships=m;expenses=e;shares=s;settlements=st;encoder=p;}
 public User register(Register x){String email=x.email().trim().toLowerCase();if(users.findByEmailIgnoreCase(email).isPresent())throw new ApiException(HttpStatus.CONFLICT,"An account with this email already exists");return users.save(new User(x.name().trim(),email,encoder.encode(x.password())));}
 public User authenticate(Login x){User u=users.findByEmailIgnoreCase(x.email().trim()).orElseThrow(()->new ApiException(HttpStatus.UNAUTHORIZED,"Email or password is incorrect"));if(!encoder.matches(x.password(),u.passwordHash))throw new ApiException(HttpStatus.UNAUTHORIZED,"Email or password is incorrect");return u;}
 public User current(String email){return users.findByEmailIgnoreCase(email).orElseThrow(()->ApiException.notFound("User not found"));}
 @Transactional public HouseholdView createHousehold(String name,User user){Household h=households.save(new Household(name.trim(),user.id));memberships.save(new Membership(h.id,user.id,"OWNER"));return householdView(h);}
 public List<HouseholdView> listHouseholds(User user){return memberships.findByUserId(user.id).stream().map(m->households.findById(m.householdId).map(this::householdView).orElse(null)).filter(Objects::nonNull).toList();}
 public HouseholdView household(Long id,User u){Household h=requireHousehold(id,u);return householdView(h);}
 @Transactional public HouseholdView addMember(Long hid,String email,User actor){Household h=requireHousehold(hid,actor);Membership own=memberships.findByHouseholdIdAndUserId(h.id,actor.id).orElseThrow();if(!own.role.equals("OWNER"))throw ApiException.forbidden("Only the household owner can add members");User add=users.findByEmailIgnoreCase(email.trim()).orElseThrow(()->ApiException.notFound("No account found for that email. Ask them to register first."));if(memberships.existsByHouseholdIdAndUserId(hid,add.id))throw ApiException.bad("This person is already in the household");memberships.save(new Membership(hid,add.id,"MEMBER"));return householdView(h);}
 @Transactional public ExpenseView createExpense(CreateExpense in,User actor){Household h=requireHousehold(in.householdId(),actor);List<Membership> ms=memberships.findByHouseholdId(h.id);Set<Long> ids=ms.stream().map(m->m.userId).collect(Collectors.toSet());if(!ids.contains(actor.id))throw ApiException.forbidden("You are not a household member");if(!Set.of("EQUAL","CUSTOM").contains(in.splitType().toUpperCase()))throw ApiException.bad("Split type must be EQUAL or CUSTOM");if(in.amount().scale()>2)throw ApiException.bad("Amounts can have at most two decimal places");if(in.splitType().equalsIgnoreCase("CUSTOM"))validateCustom(in,ids);List<Long> ordered=ms.stream().map(m->m.userId).sorted().toList();Expense e=expenses.save(new Expense(h.id,actor.id,in.description().trim(),in.category().trim().toUpperCase(),in.amount().setScale(2,RoundingMode.HALF_UP),in.expenseDate(),in.splitType().toUpperCase()));List<ShareInput> calc=in.splitType().equalsIgnoreCase("CUSTOM")?in.shares():equalShares(in.amount(),ordered);for(ShareInput s:calc)shares.save(new ExpenseShare(e.id,s.userId(),s.amount().setScale(2,RoundingMode.HALF_UP)));return expenseView(e);}
 private void validateCustom(CreateExpense in,Set<Long> ids){if(in.shares()==null||in.shares().isEmpty())throw ApiException.bad("Add custom amounts for household members");Set<Long> seen=new HashSet<>();BigDecimal sum=BigDecimal.ZERO;for(ShareInput s:in.shares()){if(!ids.contains(s.userId()))throw ApiException.bad("All split members must belong to this household");if(!seen.add(s.userId()))throw ApiException.bad("Each member can only appear once in the split");if(s.amount().scale()>2)throw ApiException.bad("Amounts can have at most two decimal places");sum=sum.add(s.amount());}if(sum.setScale(2,RoundingMode.HALF_UP).compareTo(in.amount().setScale(2,RoundingMode.HALF_UP))!=0)throw ApiException.bad("Custom split amounts must add up to the expense total");}
 List<ShareInput> equalShares(BigDecimal total,List<Long> ids){long cents=total.setScale(2,RoundingMode.HALF_UP).movePointRight(2).longValueExact();long base=cents/ids.size();int extra=(int)(cents%ids.size());List<ShareInput> out=new ArrayList<>();for(int i=0;i<ids.size();i++)out.add(new ShareInput(ids.get(i),BigDecimal.valueOf(base+(i<extra?1:0),2)));return out;}
 public PageView<ExpenseView> expensePage(Long hid,User u,int page,int size,String category){requireHousehold(hid,u);Page<Expense> p=expenses.findHouseholdExpenses(hid,category==null||category.equalsIgnoreCase("all")?null:category,PageRequest.of(Math.max(page,0),Math.min(Math.max(size,1),100)));return new PageView<>(p.getContent().stream().map(this::expenseView).toList(),p.getNumber(),p.getSize(),p.getTotalElements(),p.getTotalPages());}
 public Summary summary(Long hid,User u){requireHousehold(hid,u);List<Expense> es=expenses.findByHouseholdId(hid);Map<Long,BigDecimal> net=new HashMap<>();for(Membership m:memberships.findByHouseholdId(hid))net.put(m.userId,BigDecimal.ZERO.setScale(2));for(Expense e:es){net.merge(e.paidBy,e.amount,BigDecimal::add);for(ExpenseShare s:shares.findByExpenseId(e.id))net.merge(s.userId,s.amount.negate(),BigDecimal::add);}for(Settlement s:settlements.findByHouseholdIdOrderByCreatedAtDesc(hid))if(s.status.equals("PAID")){net.merge(s.payerId,s.amount,BigDecimal::add);net.merge(s.payeeId,s.amount.negate(),BigDecimal::add);}List<Balance> bs=net.entrySet().stream().map(e->new Balance(e.getKey(),users.findById(e.getKey()).map(x->x.name).orElse("Unknown"),e.getValue().setScale(2,RoundingMode.HALF_UP))).sorted(Comparator.comparing(Balance::name)).toList();List<Transfer> tx=transfers(net);YearMonth month=YearMonth.now();BigDecimal monthSpend=es.stream().filter(e->YearMonth.from(e.expenseDate).equals(month)).map(e->e.amount).reduce(BigDecimal.ZERO,BigDecimal::add);BigDecimal total=es.stream().map(e->e.amount).reduce(BigDecimal.ZERO,BigDecimal::add);return new Summary(monthSpend.setScale(2,RoundingMode.HALF_UP),total.setScale(2,RoundingMode.HALF_UP),es.size(),bs,tx);}
 List<Transfer> transfers(Map<Long,BigDecimal> net){record Side(Long id,BigDecimal amount){}List<Side> owes=new ArrayList<>(),gets=new ArrayList<>();net.forEach((id,n)->{if(n.signum()<0)owes.add(new Side(id,n.negate()));else if(n.signum()>0)gets.add(new Side(id,n));});owes.sort(Comparator.comparing(Side::amount).reversed());gets.sort(Comparator.comparing(Side::amount).reversed());List<Transfer> out=new ArrayList<>();int i=0,j=0;while(i<owes.size()&&j<gets.size()){Side o=owes.get(i),g=gets.get(j);BigDecimal amount=o.amount.min(g.amount).setScale(2,RoundingMode.HALF_UP);out.add(new Transfer(o.id,users.findById(o.id).orElseThrow().name,g.id,users.findById(g.id).orElseThrow().name,amount));BigDecimal oa=o.amount.subtract(amount),ga=g.amount.subtract(amount);owes.set(i,new Side(o.id,oa));gets.set(j,new Side(g.id,ga));if(oa.signum()==0)i++;if(ga.signum()==0)j++;}return out;}
 @Transactional public SettlementView createSettlement(Long hid,Long payee,BigDecimal amount,User actor){requireHousehold(hid,actor);if(!memberships.existsByHouseholdIdAndUserId(hid,payee)||payee.equals(actor.id))throw ApiException.bad("Choose another member of this household");if(amount==null||amount.signum()<=0||amount.scale()>2)throw ApiException.bad("Enter a valid amount with up to two decimal places");Settlement s=settlements.save(new Settlement(hid,actor.id,payee,amount.setScale(2)));return settlementView(s);}
 @Transactional public SettlementView markPaid(Long hid,Long id,User actor){requireHousehold(hid,actor);Settlement s=settlements.findByIdAndHouseholdId(id,hid).orElseThrow(()->ApiException.notFound("Settlement not found"));if(!s.payerId.equals(actor.id))throw ApiException.forbidden("Only the person who owes can mark this payment paid");if(!s.status.equals("PENDING"))throw ApiException.bad("This settlement has already been paid");s.status="PAID";s.paidAt=Instant.now();return settlementView(s);}
 public List<SettlementView> listSettlements(Long hid,User u){requireHousehold(hid,u);return settlements.findByHouseholdIdOrderByCreatedAtDesc(hid).stream().map(this::settlementView).toList();}
 private Household requireHousehold(Long id,User u){Household h=households.findById(id).orElseThrow(()->ApiException.notFound("Household not found"));if(!memberships.existsByHouseholdIdAndUserId(id,u.id))throw ApiException.forbidden("You are not a member of this household");return h;}
 private HouseholdView householdView(Household h){List<Member> m=memberships.findByHouseholdId(h.id).stream().map(x->{User u=users.findById(x.userId).orElseThrow();return new Member(u.id,u.name,u.email,x.role);}).toList();return new HouseholdView(h.id,h.name,m);}
 private ExpenseView expenseView(Expense e){String payer=users.findById(e.paidBy).map(x->x.name).orElse("Unknown");List<ShareInput> sh=shares.findByExpenseId(e.id).stream().map(s->new ShareInput(s.userId,s.amount)).toList();return new ExpenseView(e.id,e.householdId,e.paidBy,payer,e.description,e.category,e.amount,e.expenseDate,e.splitType,sh);}
 private SettlementView settlementView(Settlement s){return new SettlementView(s.id,s.payerId,users.findById(s.payerId).map(x->x.name).orElse("Unknown"),s.payeeId,users.findById(s.payeeId).map(x->x.name).orElse("Unknown"),s.amount,s.status,s.paidAt==null?null:s.paidAt.toString());}
}
